//! CLI <-> background daemon (`worktree-bg`) protocol.
//!
//! Transport: newline-delimited JSON over TCP on 127.0.0.1. One request line,
//! one response line per connection. The daemon writes
//! `$WT_HOME/bg.json` = `{"pid": u32, "port": u16, "version": "...",
//! "token": "..."}` on startup and removes it on clean shutdown.
//!
//! Authentication (v0.5, ENGINEERING_PLAN §13.11): `token` is a random
//! secret generated by each daemon instance ([`new_token`]). Every request
//! line carries it as a top-level `"token"` field next to `"cmd"`; the
//! daemon answers requests with a missing or wrong token with an
//! [`IpcResponse::Error`] starting with [`UNAUTHORIZED`] and never passes
//! them to its handler. Only processes that can read `bg.json` (the user's
//! own) can therefore control the daemon, although the port is reachable by
//! every local user.
//!
//! The client side is [`send`] / [`send_to`]; the server side is [`serve`],
//! which the daemon (and tests) drive with a request handler.

use std::future::Future;
use std::io::ErrorKind;
use std::net::{Ipv4Addr, SocketAddr};
use std::path::{Path, PathBuf};
use std::time::Duration;

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use tokio::io::{AsyncBufReadExt, AsyncRead, AsyncReadExt, AsyncWrite, AsyncWriteExt, BufReader};
use tokio::net::{TcpListener, TcpStream};
use tokio::task::JoinSet;

use crate::error::{Result, SdkError};

/// Timeout for connecting, writing a request and (for quick requests)
/// receiving the response.
pub const IPC_TIMEOUT: Duration = Duration::from_secs(5);

/// Response timeout for requests that may do real work in the daemon
/// (snapshotting and staging every tree of a worktree, or setting up a
/// recursive watch over a large directory).
pub const IPC_SLOW_TIMEOUT: Duration = Duration::from_secs(300);

/// Upper bound on a single protocol line; anything longer is rejected.
pub const MAX_LINE_BYTES: u64 = 1024 * 1024;

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
pub enum IpcRequest {
    Status,
    /// Start watching a worktree root.
    Watch {
        path: PathBuf,
    },
    Unwatch {
        path: PathBuf,
    },
    /// Pause/resume auto-snapshots (all worktrees if path is None).
    Pause {
        path: Option<PathBuf>,
    },
    Resume {
        path: Option<PathBuf>,
    },
    /// Take an auto-snapshot now (all trees of the worktree).
    SnapshotNow {
        path: PathBuf,
    },
    /// Sent by the CLI right before it switches `tree` of the worktree at
    /// `path` to another branch: the daemon snapshots that tree first when
    /// `auto_snapshot.on_branch_switch` is `"snapshot"` (the default).
    PrepareSwitch {
        path: PathBuf,
        tree: String,
    },
    Shutdown,
}

impl IpcRequest {
    /// How long a client waits for the response to this request.
    pub fn response_timeout(&self) -> Duration {
        match self {
            IpcRequest::Watch { .. }
            | IpcRequest::SnapshotNow { .. }
            | IpcRequest::PrepareSwitch { .. } => IPC_SLOW_TIMEOUT,
            _ => IPC_TIMEOUT,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "result", rename_all = "snake_case")]
pub enum IpcResponse {
    Status(DaemonStatus),
    Ok { message: String },
    Error { message: String },
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct DaemonStatus {
    pub pid: u32,
    pub version: String,
    pub started_at: DateTime<Utc>,
    pub watched: Vec<WatchedWorktree>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct WatchedWorktree {
    pub root: PathBuf,
    pub paused: bool,
    pub pending_changes: usize,
    pub snapshots_created: u64,
    pub last_snapshot: Option<String>,
    pub last_snapshot_at: Option<DateTime<Utc>>,
    pub last_stage_at: Option<DateTime<Utc>>,
    pub last_error: Option<String>,
    /// v0.5: when the sync loop last fetched remote branches.
    #[serde(default)]
    pub last_fetch_at: Option<DateTime<Utc>>,
    /// v0.5: sync loop state ("watching", "polling", "offline", "disabled", ...).
    #[serde(default)]
    pub sync_state: Option<String>,
    /// v0.5: the last sync failure, cleared by the next successful fetch.
    #[serde(default)]
    pub sync_error: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct DaemonInfo {
    pub pid: u32,
    pub port: u16,
    pub version: String,
    /// Secret every request must carry (empty in files written by daemons
    /// older than v0.5, which must be restarted).
    #[serde(default)]
    pub token: String,
}

/// Prefix of the error message a daemon answers unauthenticated requests with.
pub const UNAUTHORIZED: &str = "unauthorized";

/// A fresh random IPC token (two v4 UUIDs: 244 bits of OS randomness, as
/// 64 hex digits).
pub fn new_token() -> String {
    format!(
        "{}{}",
        uuid::Uuid::new_v4().simple(),
        uuid::Uuid::new_v4().simple()
    )
}

/// `$WT_HOME/bg.json`.
pub fn daemon_info_path() -> PathBuf {
    crate::config::wt_home().join("bg.json")
}

/// Read `bg.json` if present (does not check liveness).
pub fn read_daemon_info() -> Result<Option<DaemonInfo>> {
    read_daemon_info_at(&daemon_info_path())
}

/// Read a daemon info file at an explicit path (`None` if it does not exist).
pub fn read_daemon_info_at(path: &Path) -> Result<Option<DaemonInfo>> {
    match std::fs::read_to_string(path) {
        Ok(text) => Ok(Some(serde_json::from_str(&text)?)),
        Err(e) if e.kind() == ErrorKind::NotFound => Ok(None),
        Err(e) => Err(e.into()),
    }
}

/// Send one request to the running daemon, authenticated with the token
/// from bg.json. `DaemonNotRunning` if bg.json is missing or the connection
/// is refused (stale file).
pub async fn send(req: &IpcRequest) -> Result<IpcResponse> {
    let info = read_daemon_info()?.ok_or(SdkError::DaemonNotRunning)?;
    send_to(info.port, &info.token, req).await
}

/// Tell a running daemon that `tree` of the worktree at `root` is about to
/// switch branches (see [`IpcRequest::PrepareSwitch`]). Best effort: `None`
/// when no daemon is running or it does not watch the worktree, else the
/// daemon's reply.
pub async fn prepare_branch_switch(root: &Path, tree: &str) -> Option<String> {
    let req = IpcRequest::PrepareSwitch {
        path: root.to_path_buf(),
        tree: tree.to_string(),
    };
    match send(&req).await {
        Ok(IpcResponse::Ok { message }) => Some(message),
        Ok(IpcResponse::Error { message }) => {
            tracing::debug!(%message, "daemon did not prepare the branch switch");
            None
        }
        Ok(IpcResponse::Status(_)) | Err(_) => None,
    }
}

/// Send one request, carrying `token`, to a daemon listening on
/// `127.0.0.1:port`. `DaemonNotRunning` if nothing is listening there.
pub async fn send_to(port: u16, token: &str, req: &IpcRequest) -> Result<IpcResponse> {
    let addr = SocketAddr::from((Ipv4Addr::LOCALHOST, port));
    let stream = match tokio::time::timeout(IPC_TIMEOUT, TcpStream::connect(addr)).await {
        Err(_) => return Err(timeout_error("connecting to")),
        Ok(Err(e)) if e.kind() == ErrorKind::ConnectionRefused => {
            return Err(SdkError::DaemonNotRunning)
        }
        Ok(Err(e)) => return Err(e.into()),
        Ok(Ok(stream)) => stream,
    };
    let (read_half, mut write_half) = stream.into_split();

    let mut line = encode_request(token, req)?;
    line.push(b'\n');
    tokio::time::timeout(IPC_TIMEOUT, async {
        write_half.write_all(&line).await?;
        write_half.shutdown().await
    })
    .await
    .map_err(|_| timeout_error("sending a request to"))??;

    let response = tokio::time::timeout(req.response_timeout(), read_line(read_half))
        .await
        .map_err(|_| timeout_error("waiting for a response from"))??;
    match response {
        Some(text) => Ok(serde_json::from_str(&text)?),
        None => Err(SdkError::Other(
            "background daemon closed the connection without responding".into(),
        )),
    }
}

/// One request line: the request's JSON object plus a `"token"` field.
fn encode_request(token: &str, req: &IpcRequest) -> Result<Vec<u8>> {
    let mut value = serde_json::to_value(req)?;
    if let serde_json::Value::Object(map) = &mut value {
        map.insert("token".into(), serde_json::Value::String(token.into()));
    }
    Ok(serde_json::to_vec(&value)?)
}

/// Parse a request line into `(token, request)`; the token is "" if absent.
fn decode_request(line: &str) -> std::result::Result<(String, IpcRequest), String> {
    let mut value: serde_json::Value = serde_json::from_str(line).map_err(|e| e.to_string())?;
    let token = match &mut value {
        serde_json::Value::Object(map) => match map.remove("token") {
            Some(serde_json::Value::String(t)) => t,
            Some(_) => return Err("token must be a string".into()),
            None => String::new(),
        },
        _ => return Err("expected a JSON object".into()),
    };
    let req = serde_json::from_value(value).map_err(|e| e.to_string())?;
    Ok((token, req))
}

/// Compare tokens in time independent of where they differ. An empty
/// expected token matches nothing.
fn tokens_match(expected: &str, given: &str) -> bool {
    let (a, b) = (expected.as_bytes(), given.as_bytes());
    if a.is_empty() || a.len() != b.len() {
        return false;
    }
    a.iter().zip(b).fold(0u8, |acc, (x, y)| acc | (x ^ y)) == 0
}

/// Serve the IPC protocol on `listener` until `shutdown` completes.
///
/// Every connection is handled on its own task: one request line is read,
/// its token checked against `token`, the request passed to `handler`, and
/// the response written back as one line. Malformed requests and requests
/// without the right token get an [`IpcResponse::Error`] without reaching
/// the handler (an empty `token` rejects everything). After `shutdown`
/// fires no new connections are accepted, and in-flight ones get up to
/// [`IPC_TIMEOUT`] to finish (so the response to a `Shutdown` request is
/// still delivered).
pub async fn serve<H, Fut, S>(listener: TcpListener, token: String, handler: H, shutdown: S)
where
    H: Fn(IpcRequest) -> Fut + Clone + Send + 'static,
    Fut: Future<Output = IpcResponse> + Send + 'static,
    S: Future<Output = ()>,
{
    tokio::pin!(shutdown);
    let token: std::sync::Arc<str> = token.into();
    let mut connections = JoinSet::new();
    loop {
        tokio::select! {
            () = &mut shutdown => break,
            accepted = listener.accept() => match accepted {
                Ok((stream, peer)) => {
                    let handler = handler.clone();
                    let token = token.clone();
                    connections.spawn(async move {
                        if let Err(e) = handle_connection(stream, &token, handler).await {
                            tracing::debug!(%peer, error = %e, "ipc connection failed");
                        }
                    });
                }
                Err(e) => {
                    // Typically resource exhaustion; back off instead of spinning.
                    tracing::warn!(error = %e, "ipc accept failed");
                    tokio::time::sleep(Duration::from_millis(50)).await;
                }
            },
            Some(_) = connections.join_next(), if !connections.is_empty() => {}
        }
    }
    let drain = async { while connections.join_next().await.is_some() {} };
    if tokio::time::timeout(IPC_TIMEOUT, drain).await.is_err() {
        tracing::warn!("abandoning ipc connections still in flight at shutdown");
    }
}

async fn handle_connection<H, Fut>(stream: TcpStream, token: &str, handler: H) -> Result<()>
where
    H: Fn(IpcRequest) -> Fut,
    Fut: Future<Output = IpcResponse>,
{
    let (read_half, mut write_half) = stream.into_split();
    let line = tokio::time::timeout(IPC_TIMEOUT, read_line(read_half))
        .await
        .map_err(|_| timeout_error("reading a request for"))??;
    let Some(line) = line else {
        return Ok(());
    };
    let response = match decode_request(&line) {
        Ok((given, req)) if tokens_match(token, &given) => handler(req).await,
        Ok(_) => {
            tracing::warn!("rejected an ipc request with a missing or invalid token");
            IpcResponse::Error {
                message: format!(
                    "{UNAUTHORIZED}: missing or invalid daemon token \
                     (run `wt daemon restart` if this persists)"
                ),
            }
        }
        Err(e) => IpcResponse::Error {
            message: format!("invalid request: {e}"),
        },
    };
    let mut out = serde_json::to_vec(&response)?;
    out.push(b'\n');
    write_response(&mut write_half, &out).await
}

async fn write_response<W: AsyncWrite + Unpin>(writer: &mut W, bytes: &[u8]) -> Result<()> {
    tokio::time::timeout(IPC_TIMEOUT, async {
        writer.write_all(bytes).await?;
        writer.shutdown().await
    })
    .await
    .map_err(|_| timeout_error("writing a response for"))??;
    Ok(())
}

/// Read one '\n'-terminated line (terminator stripped). `None` on immediate
/// EOF; `InvalidArgument` if the line exceeds [`MAX_LINE_BYTES`].
async fn read_line<R: AsyncRead + Unpin>(reader: R) -> Result<Option<String>> {
    let mut reader = BufReader::new(reader.take(MAX_LINE_BYTES + 1));
    let mut line = String::new();
    let n = reader.read_line(&mut line).await?;
    if n == 0 {
        return Ok(None);
    }
    if n as u64 > MAX_LINE_BYTES {
        return Err(SdkError::InvalidArgument(format!(
            "ipc message exceeds {MAX_LINE_BYTES} bytes"
        )));
    }
    let trimmed = line.trim_end_matches(['\n', '\r']);
    Ok(Some(trimmed.to_owned()))
}

fn timeout_error(action: &str) -> SdkError {
    SdkError::Other(format!("timed out {action} the background daemon"))
}

#[cfg(test)]
mod tests {
    use super::*;

    use std::sync::atomic::{AtomicU64, Ordering};
    use std::sync::Arc;

    use tokio::sync::{oneshot, Notify};

    const TOKEN: &str = "test-token-0123456789";

    /// A unique scratch directory under the system temp dir, removed on drop.
    struct ScratchDir(PathBuf);

    impl ScratchDir {
        fn new() -> Self {
            static COUNTER: AtomicU64 = AtomicU64::new(0);
            let n = COUNTER.fetch_add(1, Ordering::Relaxed);
            let dir = std::env::temp_dir().join(format!("wt-ipc-test-{}-{n}", std::process::id()));
            std::fs::create_dir_all(&dir).expect("create scratch dir");
            Self(dir)
        }
    }

    impl Drop for ScratchDir {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.0);
        }
    }

    fn sample_status() -> DaemonStatus {
        DaemonStatus {
            pid: 42,
            version: "0.1.0".into(),
            started_at: Utc::now(),
            watched: vec![WatchedWorktree {
                root: PathBuf::from("/work/project"),
                paused: true,
                pending_changes: 3,
                snapshots_created: 7,
                last_snapshot: Some("abcd1234".into()),
                last_snapshot_at: Some(Utc::now()),
                last_stage_at: None,
                last_error: Some("boom".into()),
                last_fetch_at: Some(Utc::now()),
                sync_state: Some("watching".into()),
                sync_error: None,
            }],
        }
    }

    /// Serve `handler` on an ephemeral port; returns the port and a trigger
    /// that stops the server, plus the server task.
    async fn spawn_server<H, Fut>(
        handler: H,
    ) -> (u16, oneshot::Sender<()>, tokio::task::JoinHandle<()>)
    where
        H: Fn(IpcRequest) -> Fut + Clone + Send + 'static,
        Fut: Future<Output = IpcResponse> + Send + 'static,
    {
        let listener = TcpListener::bind((Ipv4Addr::LOCALHOST, 0))
            .await
            .expect("bind");
        let port = listener.local_addr().expect("local addr").port();
        let (stop_tx, stop_rx) = oneshot::channel::<()>();
        let task = tokio::spawn(serve(listener, TOKEN.into(), handler, async {
            let _ = stop_rx.await;
        }));
        (port, stop_tx, task)
    }

    async fn fake_handler(req: IpcRequest) -> IpcResponse {
        match req {
            IpcRequest::Status => IpcResponse::Status(DaemonStatus {
                pid: 1,
                version: "test".into(),
                started_at: DateTime::<Utc>::from_timestamp(0, 0).expect("epoch"),
                watched: Vec::new(),
            }),
            IpcRequest::Watch { path } => IpcResponse::Ok {
                message: format!("watching {}", path.display()),
            },
            other => IpcResponse::Error {
                message: format!("unsupported: {other:?}"),
            },
        }
    }

    #[test]
    fn request_wire_format_is_tagged_snake_case() {
        let json = serde_json::to_value(IpcRequest::SnapshotNow { path: "/a".into() }).unwrap();
        assert_eq!(
            json,
            serde_json::json!({"cmd": "snapshot_now", "path": "/a"})
        );
        let json = serde_json::to_value(IpcRequest::Pause { path: None }).unwrap();
        assert_eq!(json, serde_json::json!({"cmd": "pause", "path": null}));
        let parsed: IpcRequest = serde_json::from_str(r#"{"cmd":"shutdown"}"#).unwrap();
        assert_eq!(parsed, IpcRequest::Shutdown);
    }

    #[test]
    fn response_round_trips_through_json() {
        for resp in [
            IpcResponse::Status(sample_status()),
            IpcResponse::Ok {
                message: "fine".into(),
            },
            IpcResponse::Error {
                message: "bad".into(),
            },
        ] {
            let text = serde_json::to_string(&resp).unwrap();
            assert!(!text.contains('\n'), "responses must be single-line");
            let back: IpcResponse = serde_json::from_str(&text).unwrap();
            assert_eq!(back, resp);
        }
        let ok = serde_json::to_value(IpcResponse::Ok {
            message: "m".into(),
        })
        .unwrap();
        assert_eq!(ok, serde_json::json!({"result": "ok", "message": "m"}));
    }

    #[test]
    fn slow_requests_get_longer_timeouts() {
        assert_eq!(IpcRequest::Status.response_timeout(), IPC_TIMEOUT);
        assert_eq!(IpcRequest::Shutdown.response_timeout(), IPC_TIMEOUT);
        let snap = IpcRequest::SnapshotNow { path: "/a".into() };
        assert_eq!(snap.response_timeout(), IPC_SLOW_TIMEOUT);
        let watch = IpcRequest::Watch { path: "/a".into() };
        assert_eq!(watch.response_timeout(), IPC_SLOW_TIMEOUT);
    }

    #[test]
    fn daemon_info_missing_file_is_none() {
        let dir = ScratchDir::new();
        assert_eq!(read_daemon_info_at(&dir.0.join("bg.json")).unwrap(), None);
    }

    #[test]
    fn daemon_info_reads_written_file() {
        let dir = ScratchDir::new();
        let path = dir.0.join("bg.json");
        std::fs::write(
            &path,
            r#"{"pid": 1234, "port": 50123, "version": "0.1.0", "token": "t0k"}"#,
        )
        .unwrap();
        let info = read_daemon_info_at(&path).unwrap();
        assert_eq!(
            info,
            Some(DaemonInfo {
                pid: 1234,
                port: 50123,
                version: "0.1.0".into(),
                token: "t0k".into(),
            })
        );
        // Files written by pre-v0.5 daemons have no token.
        std::fs::write(&path, r#"{"pid": 1, "port": 2, "version": "0.4"}"#).unwrap();
        assert_eq!(read_daemon_info_at(&path).unwrap().unwrap().token, "");
    }

    #[test]
    fn tokens_are_random_and_compared_exactly() {
        let (a, b) = (new_token(), new_token());
        assert_eq!(a.len(), 64);
        assert!(a.chars().all(|c| c.is_ascii_hexdigit()));
        assert_ne!(a, b);
        assert!(tokens_match(&a, &a.clone()));
        assert!(!tokens_match(&a, &b));
        assert!(!tokens_match(&a, &a[..63]));
        assert!(!tokens_match(&a, ""));
        assert!(
            !tokens_match("", ""),
            "an empty expected token matches nothing"
        );
    }

    #[test]
    fn request_lines_carry_the_token() {
        let line = encode_request("sekrit", &IpcRequest::Pause { path: None }).unwrap();
        let value: serde_json::Value = serde_json::from_slice(&line).unwrap();
        assert_eq!(
            value,
            serde_json::json!({"cmd": "pause", "path": null, "token": "sekrit"})
        );
        let (token, req) = decode_request(std::str::from_utf8(&line).unwrap()).unwrap();
        assert_eq!(token, "sekrit");
        assert_eq!(req, IpcRequest::Pause { path: None });
        let (token, req) = decode_request(r#"{"cmd":"status"}"#).unwrap();
        assert_eq!((token.as_str(), req), ("", IpcRequest::Status));
        assert!(decode_request(r#"{"cmd":"status","token":5}"#).is_err());
        assert!(decode_request("[1]").is_err());
    }

    #[tokio::test]
    async fn requests_without_the_right_token_are_rejected() {
        let calls = Arc::new(AtomicU64::new(0));
        let handler = {
            let calls = calls.clone();
            move |req: IpcRequest| {
                calls.fetch_add(1, Ordering::SeqCst);
                fake_handler(req)
            }
        };
        let (port, stop, task) = spawn_server(handler).await;
        for token in ["", "wrong", &TOKEN[..TOKEN.len() - 1]] {
            match send_to(port, token, &IpcRequest::Shutdown).await.unwrap() {
                IpcResponse::Error { message } => {
                    assert!(message.starts_with(UNAUTHORIZED), "{message}")
                }
                other => panic!("token {token:?} accepted: {other:?}"),
            }
        }
        // A raw line without any token field is rejected too.
        let mut stream = TcpStream::connect((Ipv4Addr::LOCALHOST, port))
            .await
            .unwrap();
        stream.write_all(b"{\"cmd\":\"status\"}\n").await.unwrap();
        stream.shutdown().await.unwrap();
        let line = read_line(stream).await.unwrap().expect("a response line");
        assert!(line.contains(UNAUTHORIZED), "{line}");
        assert_eq!(calls.load(Ordering::SeqCst), 0, "handler must not run");

        assert!(matches!(
            send_to(port, TOKEN, &IpcRequest::Status).await.unwrap(),
            IpcResponse::Status(_)
        ));
        assert_eq!(calls.load(Ordering::SeqCst), 1);
        stop.send(()).unwrap();
        task.await.unwrap();
    }

    #[test]
    fn daemon_info_corrupt_file_is_serialization_error() {
        let dir = ScratchDir::new();
        let path = dir.0.join("bg.json");
        std::fs::write(&path, "not json").unwrap();
        assert!(matches!(
            read_daemon_info_at(&path),
            Err(SdkError::Serialization(_))
        ));
    }

    #[tokio::test]
    async fn round_trip_status_ok_and_error() {
        let (port, stop, task) = spawn_server(fake_handler).await;

        match send_to(port, TOKEN, &IpcRequest::Status).await.unwrap() {
            IpcResponse::Status(status) => {
                assert_eq!(status.pid, 1);
                assert_eq!(status.version, "test");
                assert!(status.watched.is_empty());
            }
            other => panic!("unexpected response {other:?}"),
        }

        let resp = send_to(
            port,
            TOKEN,
            &IpcRequest::Watch {
                path: "proj".into(),
            },
        )
        .await
        .unwrap();
        assert_eq!(
            resp,
            IpcResponse::Ok {
                message: "watching proj".into()
            }
        );

        let resp = send_to(port, TOKEN, &IpcRequest::Shutdown).await.unwrap();
        assert_eq!(
            resp,
            IpcResponse::Error {
                message: "unsupported: Shutdown".into()
            }
        );

        stop.send(()).unwrap();
        task.await.unwrap();
    }

    #[tokio::test]
    async fn concurrent_clients_are_served() {
        let (port, stop, task) = spawn_server(fake_handler).await;
        let mut clients = JoinSet::new();
        for _ in 0..16 {
            clients.spawn(async move { send_to(port, TOKEN, &IpcRequest::Status).await });
        }
        while let Some(result) = clients.join_next().await {
            assert!(matches!(result.unwrap().unwrap(), IpcResponse::Status(_)));
        }
        stop.send(()).unwrap();
        task.await.unwrap();
    }

    #[tokio::test]
    async fn malformed_request_gets_error_response() {
        let (port, stop, task) = spawn_server(fake_handler).await;
        let mut stream = TcpStream::connect((Ipv4Addr::LOCALHOST, port))
            .await
            .unwrap();
        stream.write_all(b"{\"cmd\":\"explode\"}\n").await.unwrap();
        stream.shutdown().await.unwrap();
        let line = read_line(stream).await.unwrap().expect("a response line");
        match serde_json::from_str::<IpcResponse>(&line).unwrap() {
            IpcResponse::Error { message } => assert!(message.starts_with("invalid request")),
            other => panic!("unexpected response {other:?}"),
        }
        stop.send(()).unwrap();
        task.await.unwrap();
    }

    #[tokio::test]
    async fn connection_refused_is_daemon_not_running() {
        // Bind then drop to obtain a port that (almost certainly) nobody serves.
        let port = {
            let l = TcpListener::bind((Ipv4Addr::LOCALHOST, 0)).await.unwrap();
            l.local_addr().unwrap().port()
        };
        let err = send_to(port, TOKEN, &IpcRequest::Status).await.unwrap_err();
        assert!(matches!(err, SdkError::DaemonNotRunning), "got {err:?}");
    }

    #[tokio::test]
    async fn shutdown_response_is_delivered_before_server_stops() {
        let stop = Arc::new(Notify::new());
        let handler = {
            let stop = stop.clone();
            move |req: IpcRequest| {
                let stop = stop.clone();
                async move {
                    if req == IpcRequest::Shutdown {
                        stop.notify_one();
                        // Give the accept loop a chance to observe shutdown first.
                        tokio::task::yield_now().await;
                    }
                    IpcResponse::Ok {
                        message: "bye".into(),
                    }
                }
            }
        };
        let listener = TcpListener::bind((Ipv4Addr::LOCALHOST, 0)).await.unwrap();
        let port = listener.local_addr().unwrap().port();
        let server = {
            let stop = stop.clone();
            tokio::spawn(serve(listener, TOKEN.into(), handler, async move {
                stop.notified().await
            }))
        };

        let resp = send_to(port, TOKEN, &IpcRequest::Shutdown).await.unwrap();
        assert_eq!(
            resp,
            IpcResponse::Ok {
                message: "bye".into()
            }
        );
        tokio::time::timeout(Duration::from_secs(10), server)
            .await
            .expect("server stops after shutdown")
            .unwrap();
        assert!(matches!(
            send_to(port, TOKEN, &IpcRequest::Status).await,
            Err(SdkError::DaemonNotRunning)
        ));
    }

    #[tokio::test]
    async fn oversized_line_is_rejected() {
        let big = vec![b'x'; (MAX_LINE_BYTES + 10) as usize];
        let err = read_line(&big[..]).await.unwrap_err();
        assert!(matches!(err, SdkError::InvalidArgument(_)));
        assert_eq!(read_line(&b""[..]).await.unwrap(), None);
        assert_eq!(
            read_line(&b"abc\r\n"[..]).await.unwrap(),
            Some("abc".into())
        );
    }
}
